entries[302187] = { ["name"] = "Highborne Compendium of Swirling Tides", ["text"] = "2.5 sec cast\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment (50), Maroon Ink (45), Ultramarine Ink (25), Expulsom (2)\nCraft a Highborne Compendium of Swirling Tides.\nProfession:\nBattle for Azeroth Inscription (160)\nTrainer:\nNarv\nZone:\nNazjatar\nCost:\n90\n\nHighborne Compendium of Swirling Tides\nBinds when equipped\nUnique-EquippedTrinket\n+7 Intellect\nEquip: Your healing spells have a chance to grant an ally an absorption shield that absorbs up to 153 damage for 12 sec. While the shield is active, the targets Primary Stat is increased by 6 .\n50" }
entries[302188] = { ["name"] = "Highborne Compendium of Sundering", ["text"] = "2.5 sec cast\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment (50), Maroon Ink (45), Ultramarine Ink (25), Expulsom (2)\nCraft a Highborne Compendium of Sundering.\nProfession:\nBattle for Azeroth Inscription (160)\nTrainer:\nNarv\nZone:\nNazjatar\nCost:\n90\n\nHighborne Compendium of Sundering\nBinds when equipped\nUnique-EquippedTrinket\n+7 [Agility or Strength] Equip: Your attacks have a chance to inflict Volcanic Pressure on the enemy, dealing 3 Fire damage every 2 sec for 10 sec. When Volcanic Pressure reaches 6 stacks it erupts, dealing 44 Fire damage to all nearby enemies.\n50" }
entries[302189] = { ["name"] = "Highborne Compendium of Storms", ["text"] = "2.5 sec cast\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment (50), Maroon Ink (45), Ultramarine Ink (25), Expulsom (2)\nCraft a Highborne Compendium of Storms.\nProfession:\nBattle for Azeroth Inscription (160)\nTrainer:\nNarv\nZone:\nNazjatar\nCost:\n90\n\nHighborne Compendium of Storms\nBinds when equipped\nUnique-EquippedTrinket\n+7 Intellect\nEquip: Your spells have a chance to conjure a typhoon that travels towards enemies dealing 16 Nature damage and grant you 4 Haste for 15 sec, up to ( 4 * 4) Haste.\n50" }
entries[302190] = { ["name"] = "Highborne Compendium of Mystical Bulwark", ["text"] = "2.5 sec cast\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment (50), Maroon Ink (45), Ultramarine Ink (25), Expulsom (2)\nCraft a Highborne Compendium of Mystical Bulwark.\nProfession:\nBattle for Azeroth Inscription (160)\nTrainer:\nNarv\nZone:\nNazjatar\nCost:\n90\n\nHighborne Compendium of Mystical Bulwark\nBinds when equipped\nUnique-EquippedTrinket\n+7 [Agility or Strength] Equip: When you take damage, you have a chance to heal for 78 health and gain 9 Armor for 10 sec, stacking up to ( 9 * 4) Armor.\n50" }
